import json,pathlib,html,hashlib
P=pathlib.Path(__file__).parent
inventory=json.loads((P/'initial-inventory.json').read_text())
chosen=['D2232-1-1','D2232-1-2','D2232-2','R2232-1-5','D2232-3','D2232-7']
sources=[];before=[]
for n in chosen:
    v=[x for x in inventory if x['number']==n]
    assert len(v)==1,n
    x=v[0]
    sources.append({'code_id':x['code_id'],'source_id':x['id'],'number':x['number'],'source_sha256':x['source_sha256'],'source_xml':x['content_xml'],'source_notes_xml':x['source_notes_xml'],'valid_from':x['valid_from'],'valid_until':x['valid_until'],'state':x['state'],'archive':x['archive']})
    before.append({'code_id':x['code_id'],'source_id':x['id'],'number':n,'source_sha256':x['source_sha256'],'draft':x['current_draft']})
data={}
def add(n,paragraphs,reason,benefit,removed,notes,repeal=False):
    data[n]={'proposed_xml':''.join('<p>'+html.escape(x,quote=False)+'</p>' for x in paragraphs),'reason':reason,'benefit_review':benefit,'review_notes':notes,'change_type':'full_repeal' if repeal else 'normative_reduction','removed_provisions':removed,'reform_policy_id':'editorial_direction_2026_10_19'}
    if repeal:data[n].update(repeal_policy_id='editorial_direction_2026_10_19',repeal_scope='Suppression prospective des seules formalités propres à la transmission supplémentaire obligatoire des accords à la CPPNI, supprimée par L2232-9 réécrit.')

add('D2232-1-1',[
"Le présent article est abrogé à compter de l'entrée en vigueur de la suppression, à l'article L. 2232-9, de la transmission supplémentaire obligatoire des accords d'entreprise à la commission paritaire permanente de négociation et d'interprétation.",
"A compter de cette date, l'insertion obligatoire d'une adresse dans l'accord instituant la commission, sa transmission au ministère et les notifications de changement imposées sur le seul fondement du présent article ne sont plus exigées. Aucun rapport, déclaration ou formalité de remplacement n'est institué.",
"Cette abrogation ne supprime ni la commission, ni la possibilité de rendre publiques ses coordonnées, ni les droits et moyens de contact prévus par les conventions et accords demeurés applicables. Les coordonnées déjà publiées peuvent continuer à être utilisées et actualisées à partir d'informations disponibles, sans nouvelle obligation déclarative."
],"Abrogation du circuit d'adresses conçu exclusivement pour la transmission des accords à la CPPNI devenue sans objet. Pas de rétablissement de la déclaration sous un autre nom ; la commission et ses coordonnées utiles restent possibles.",
"La CPPNI conserve ses missions et la faculté de publier ses coordonnées ; aucun droit conventionnel de la joindre ou moyen de contact accordé aux salariés n'est supprimé. Seules les obligations déclaratives liées au circuit légal retiré cessent.",
["Insertion obligatoire d'une adresse pour le circuit de transmission supplémentaire supprimé.","Transmission supplétive de cette adresse au ministère et notification obligatoire de ses changements."],
"Source actuelle confirmée LEGIARTI000033500179, note DILA vide. L2232-9 réécrit conserve la CPPNI et L441-1 COJ la saisine pour avis. L'abrogation est coordonnée dans le temps avec celle du circuit, pas avec une suppression de la commission.",True)

add('D2232-1-2',[
"Le présent article est abrogé à compter de l'entrée en vigueur de la suppression, à l'article L. 2232-9, de la transmission supplémentaire obligatoire des accords d'entreprise à la commission paritaire permanente de négociation et d'interprétation.",
"Dès cette date, aucune transmission, information des autres signataires, anonymisation supplémentaire ou délivrance d'un accusé de réception ne peut être exigée sur le seul fondement du présent article, y compris pour un accord antérieur dont la transmission n'a pas encore été réalisée.",
"Les actes déjà accomplis restent acquis. Le dépôt légal, la publicité des accords, les règles autonomes de confidentialité et de protection des données et les engagements conventionnels demeurés applicables ne sont pas supprimés par cette abrogation. Aucune formalité de remplacement n'est créée."
],"Suppression intégrale de l'envoi supplémentaire des accords, de l'information parallèle des signataires, de l'anonymisation propre à cette nouvelle copie et de l'accusé de réception. Les règles générales de dépôt/publicité et de confidentialité restent distinctes.",
"La dispense nouvelle de transmission bénéficie aussi aux accords déjà conclus sans exiger un rattrapage. Les parties conservent leurs engagements conventionnels, leur confidentialité et les protections applicables aux données ; aucune nouvelle copie n'est nécessaire pour conserver un avantage.",
["Transmission systématique des accords de temps de travail, repos et congés à la CPPNI.","Information supplémentaire des autres signataires, anonymisation d'une nouvelle copie et accusé de réception propres à cet envoi."],
"Le numéro exact est D2232-1-2, LEGIARTI000033500184, note DILA vide. Aucun R2232-1-2 ne lui est substitué. La publicité prévue par L2231-5-1 n'est pas abrogée.",True)

add('D2232-2',[
"L'approbation des salariés prévue aux articles L. 2232-12, L. 2232-23-1, L. 2232-24 et L. 2232-26 est recueillie dans les conditions suivantes :",
"1° La consultation se déroule pendant le temps de travail, au scrutin personnel et secret, sous enveloppe ou par voie électronique. Son organisation matérielle incombe à l'employeur. Le recours à la voie électronique respecte les garanties des articles R. 2314-6 à R. 2314-10, R. 2314-12 et R. 2314-14 à R. 2314-18, adaptées à une consultation sur un accord. Il assure notamment la confidentialité, la sécurité de l'authentification et du dépouillement, la séparation des données d'identité et de vote, le scellement, l'expertise indépendante, l'assistance technique, l'information des salariés, la formation des personnes chargées du scrutin, le contrôle des opérations et la conservation des preuves jusqu'à l'expiration des recours ou leur règlement définitif, suivie de leur destruction.",
"Pour appliquer l'article R. 2314-15, les personnes habilitées à contrôler le scrutin en application de ses modalités d'organisation assistent aux opérations prévues par cet article ; aucune liste de candidats n'a à être constituée pour la consultation. Le recours à ces garanties n'impose pas un protocole préélectoral ni un accord distinct sur le vote électronique : les modalités sont déterminées selon les règles propres à la consultation concernée, notamment celles de l'article L. 2232-12 lorsqu'il s'applique. La description technique et les informations déjà à jour et accessibles peuvent être reprises par référence, sans copie supplémentaire.",
"Les obligations de protection des données applicables, notamment celles du règlement (UE) 2016/679, demeurent respectées. Le présent article ne rétablit pas une déclaration préalable générale à la Commission nationale de l'informatique et des libertés ; les consultations ou autres mesures spécialement requises par la législation sur les données personnelles subsistent.",
"2° Le résultat est consigné dans un procès-verbal rendu public dans l'entreprise par tout moyen et annexé à l'accord approuvé lors de son dépôt. Lorsqu'un représentant élu mandaté ou un salarié mandaté a conclu l'accord, le procès-verbal est également adressé à l'organisation qui l'a mandaté."
],"Remplacement du renvoi réellement abrogé R2324-5 à R2324-17 par les garanties techniques actuelles correspondantes : R2314-6 à R2314-18, hors formalité déclarative CNIL ancienne et protocole préélectoral distinct. Le vote électronique reste une faculté, sans nouvel accord distinct imposé ; les garanties techniques, le procès-verbal et les recours ne sont pas supprimés.",
"Le choix entre enveloppe et voie électronique est conservé, avec le temps de travail et l'organisation matérielle à la charge de l'employeur. Les salariés gardent un vote personnel, secret, sécurisé, contrôlable et contestable ; aucune déclaration générale CNIL obsolète n'est recréée pour accéder à cette faculté.",
["Renvoi aux articles R2324-5 à R2324-17 abrogés depuis le 1er janvier 2018.","Transposition au référendum d'un protocole préélectoral distinct ou d'une ancienne déclaration CNIL générale ; seules les modalités propres à la consultation et les obligations autonomes de données subsistent.","Nouvelle copie de descriptions techniques déjà à jour et effectivement accessibles."],
"Source et deux paragraphes de notes DILA lus en entier ; notes historiques de 2016 conservées dans la source, pas réactivées. Les correspondances sont décalées d'un numéro : ancien R2324-5 vers R2314-6, ancien R2324-17 vers R2314-18. Les articles R2314-11 (déclaration CNIL) et R2314-13 (protocole préélectoral) ne sont pas importés aveuglément. CNIL, questions-réponses sur les élections professionnelles, rubrique 6 : pas de formalité générale préalable ; RGPD, AIPD et consultation si risque résiduel élevé restent autonomes. La portée de la réglementation des données n'est pas déclarée entièrement réécrite.")

add('R2232-1-5',[
"La prise en charge prévue à l'article L. 2232-8 repose sur un montant forfaitaire par journée ou demi-journée de participation du salarié.",
"L'employeur demande cette prise en charge à l'association mentionnée à l'article L. 2135-15 en permettant d'établir l'identité du salarié ainsi que l'objet, la date et la durée de sa participation aux réunions de négociation. L'attestation nominative de participation établie par l'organisation syndicale concernée peut établir cette participation. Lorsque le fonds possède déjà les informations ou les pièces probantes relatives à la même participation, il les réutilise : l'employeur n'a pas à les joindre à nouveau et aucune nouvelle attestation n'est exigée. Seuls les éléments nécessaires qui manquent peuvent être demandés.",
"La rémunération correspondante est versée par l'employeur au plus tard dans le mois qui suit la réception de l'attestation de participation ou des informations probantes équivalentes établissant cette participation, sans préjudice d'une échéance de paiement plus favorable au salarié. Le versement ne dépend pas du remboursement de l'employeur par le fonds.",
"La demande de prise en charge est adressée dans les six mois suivant la réception de l'attestation de l'organisation syndicale. Lorsque la participation est établie sans nouvelle attestation, ce délai court de la réception par l'employeur des informations probantes équivalentes ; l'antériorité de la seule détention de données par le fonds ne réduit pas le délai de l'employeur.",
"Le fonds rembourse le montant total des sommes forfaitaires à sa charge pour les salariés de l'employeur ayant participé aux négociations de branche dans les quatre-vingt-dix jours suivant la réception d'une demande complète. La complétude tient compte des pièces et informations déjà détenues par le fonds ; elle ne peut être reportée par l'exigence de les fournir à nouveau.",
"La demande peut être présentée sur tout support permettant de communiquer les éléments nécessaires. Le modèle établi par arrêté du ministre chargé du travail reste utilisable à titre facultatif ; son utilisation, la reproduction de ses rubriques déjà renseignées et la production de justificatifs déjà détenus ne peuvent conditionner la prise en charge. Aucune formalité de remplacement n'est créée.",
"Ces dispenses s'appliquent aux demandes présentées ou encore en cours d'examen à l'entrée en vigueur de la présente rédaction. Elles ne réduisent aucun délai déjà ouvert, ne remettent pas en cause une prise en charge accordée et n'imposent pas de refaire un dossier complet ou une attestation déjà valablement établis."
],"Coordination du réemploi des preuves autorisé par L2232-8 : plus d'attestation répétée ni de copie de données déjà détenues, modèle facultatif, demande complète appréciée avec l'existant. Les forfaits, la durée par journée ou demi-journée, le délai de demande et le remboursement sous quatre-vingt-dix jours sont conservés. Le salaire ne peut être suspendu en attente d'une attestation répétée ou du remboursement.",
"La prise en charge demeure ouverte aux participations futures, avec les montants forfaitaires applicables et les cotisations incluses par L2232-8. Le délai de six mois n'est pas avancé à la date d'une donnée que seul le fonds détenait, les droits des demandes en cours sont conservés et l'usage de l'ancien modèle reste possible sans être obligatoire.",
["Attestation de participation nouvelle ou copies de justificatifs alors que le fonds détient déjà les preuves de la même participation.","Usage contraignant du modèle ministériel et nouvelle saisie de rubriques déjà renseignées.","Report de la complétude et du remboursement pour obtenir une seconde copie d'informations déjà probantes."],
"LEGIARTI000036405189 confirmé actuel, note DILA vide. R2232-1-3 (seuil) et R2232-1-4 (imputation sur les crédits de l'année de demande complète) sont conservés ; la présente rédaction n'invente ni taux ni forfait. L'arrêté du 23 mai 2019, NOR MTRT1915162A, JORFTEXT000038578619, comporte un modèle et une notice dont les exigences doivent être coordonnées : identification vérifiée par source primaire indexée, mais texte entier inaccessible au moment de la préparation (403 officiel). Aucun faux compagnon de cet arrêté n'est déclaré rédigé ; la norme réglementaire supérieure rend déjà le modèle facultatif et interdit les doubles pièces.")

add('D2232-3',[
"Les modalités de la consultation déterminent :",
"1° Comment les salariés reçoivent le texte de la convention ou de l'accord ;",
"2° Le lieu, la date et l'heure du scrutin ;",
"3° L'organisation et le déroulement du vote ;",
"4° Le texte de la question soumise aux salariés.",
"Dans le cas prévu à l'article L. 2232-12, ces modalités peuvent être arrêtées en reprenant expressément, dans les conditions de cet article, des dispositions antérieurement convenues et toujours adaptées au scrutin. Un document matériellement distinct ou la reproduction des mêmes dispositions n'est pas exigé. Le renvoi identifie les dispositions applicables et ne dispense d'aucune information des salariés, d'aucune garantie du vote ni de l'accord exprès des parties compétentes."
],"Coordination du réemploi accepté du protocole de L2232-12, sans document supplémentaire. Les quatre informations indispensables au choix et au contrôle du vote restent déterminées et portées à la connaissance des salariés selon D2232-4.",
"Les salariés conservent le texte soumis au vote, la date, le lieu, les règles d'organisation et la question exacte. Le réemploi n'est possible qu'avec les parties requises par L2232-12 et ne réduit ni l'information, ni la réflexion, ni le contrôle du scrutin.",
["Document matériellement distinct et reproduction de modalités identiques lorsque le réemploi a été expressément convenu selon L2232-12."],
"Version actuelle LEGIARTI000036195209 confirmée, note DILA vide. Ce texte de 2017 n'est pas l'ancienne version annulée LEGIARTI000036001377 ; celle-ci n'est pas réactivée. D2232-4 (quinze jours d'information) reste inchangé.")

add('D2232-7',[
"Les organisations syndicales représentatives dans l'entreprise ou l'établissement peuvent saisir le président du tribunal judiciaire d'un désaccord sur les modalités d'organisation de la consultation. Il statue selon la procédure accélérée au fond et en dernier ressort.",
"Si le président du tribunal n'est pas saisi dans les huit jours suivant la notification de ces modalités, celles-ci s'appliquent sous réserve de satisfaire aux conditions légales de leur adoption. Lorsque l'article L. 2232-12 exige l'accord de l'employeur et d'organisations syndicales, cette absence de saisine ne vaut ni accord sur un protocole, ni acceptation d'un renvoi à un protocole antérieur, ni autorisation pour l'employeur d'imposer seul des modalités qui n'ont pas été valablement convenues."
],"Suppression de l'apparence d'une validation unilatérale des modalités faute de recours en huit jours. La procédure de contestation et son délai restent intacts, mais le silence contentieux ne remplace pas le consentement expressément requis par L2232-12 pour les modalités nouvelles ou réutilisées.",
"Les organisations représentatives conservent le recours rapide au juge. L'absence de saisine ne prive pas les parties du consentement requis et n'autorise pas un protocole imposé ; le réemploi favorable d'un protocole reste disponible lorsqu'il est valablement accepté.",
["Effet apparent de validation de modalités décidées unilatéralement par l'employeur du seul fait de l'absence de recours, lorsque leur adoption requiert un accord selon L2232-12."],
"Version actuelle LEGIARTI000039726081 et ses deux notes d'application 2019 lues. La procédure accélérée au fond et le dernier ressort sont conservés. Aucun délai nouveau n'est créé ; les autres voies de contestation d'un accord ou du scrutin ne sont pas supprimées.")

answers=[]
for s in sources:
    n=s['number'];a={k:s[k] for k in ('code_id','source_id','number','source_sha256')};a.update(status='rewrite_draft',**data[n]);answers.append(a)
for f,d in [('source.json',sources),('answer.json',answers),('beforeimages.json',before)]:
    t=P/(f+'.tmp');t.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');t.replace(P/f)
print('articles',len(answers),'answer_sha256',hashlib.sha256((P/'answer.json').read_bytes()).hexdigest())
